from structure import C,E

C('Émettre et transmettre un son','son',[
'Expliquer émission, propagation et réception d’un son.',
'Relier distance, durée et vitesse de propagation.',
'Concevoir une mesure avec deux microphones.'],[
('Une vibration et un milieu',r'''Une corde, une membrane ou une lame qui vibre peut mettre le milieu environnant en vibration. Une caisse de résonance facilite le couplage avec l'air et peut renforcer le son émis. Le signal sonore se propage de proche en proche dans un milieu matériel ; il ne se propage pas dans le vide.
\schema{propagation-son}
Les particules du milieu oscillent autour de leur position ; elles ne voyagent pas toutes de la source jusqu'à l'auditeur. Une onde transporte une perturbation et de l'énergie, sans transport global de matière sur cette distance.'''),
('Une vitesse de propagation',r'''\begin{loi}[Propagation dans un milieu uniforme]Pour une distance parcourue $d$ et une durée de propagation $\Delta t$, $v=d/\Delta t$. Dans l'air proche de la température ambiante, on utilise souvent $v\simeq\qty{340}{m.s^{-1}}$. La valeur dépend du milieu et de ses conditions.\end{loi}
Le son se propage généralement plus vite dans l'eau que dans l'air. Les valeurs nécessaires sont données dans les exercices. La vitesse de propagation du signal n'est pas la vitesse de vibration d'une particule du milieu.
\begin{exemple}[Un écho]Un obstacle renvoie un signal en 0,200 s. Le trajet est un aller-retour : $2d=v\Delta t$, donc $d=340\times0,200/2=\qty{34,0}{m}$.\end{exemple}'''),
('Mesurer un retard',r'''Deux microphones séparés d'une distance connue reçoivent un même signal à des dates différentes. Si la source et les microphones sont alignés dans le bon ordre, la différence de trajets vaut la distance entre les microphones.
\schema{retard-son}
\begin{savoirfaire}[Une mesure exploitable]Repérer le même détail du signal sur les deux enregistrements ; lire le retard et non la durée totale de l'acquisition ; vérifier les unités de temps. Augmenter raisonnablement la distance peut rendre le retard plus facile à mesurer.\end{savoirfaire}''')],
r'''\begin{experience}[Mesurer la vitesse du son]Aligner une source impulsionnelle et deux microphones. Mesurer leur séparation, enregistrer simultanément, lire le retard et calculer $v$. Refaire à plusieurs distances, discuter les échos de la salle et la lecture temporelle. Employer un signal bref de niveau raisonnable ; ne pas produire de choc sonore près des oreilles.\end{experience}''',[
E('Une source sonore',r'Une corde de guitare est pincée.',[r'Quel objet vibre à l’origine du son ?',r'Quel intérêt présente la caisse de la guitare ?'],[r'La corde se met en vibration.',r'La caisse aide à transmettre les vibrations à un plus grand volume d’air et peut renforcer le son émis.']),
E('Le rôle du milieu',r'Une sonnerie est placée dans une enceinte dont on retire progressivement l’air.',[r'Pourquoi le son transmis à travers le gaz s’affaiblit-il ?',r'Un son pourrait-il traverser un vide parfait ?'],[r'Le milieu matériel devient moins dense pour transmettre les vibrations ; d’autres transmissions par les supports peuvent subsister.',r'Non, le son nécessite un milieu matériel.'],'propagation-son'),
E('Une durée de propagation',r'Un signal parcourt 68,0 m dans l’air à 340 m/s.',[r'Calculer sa durée de propagation.',r'Exprimer cette durée en millisecondes.'],[r'$\Delta t=d/v=68,0/340=\qty{0,200}{s}$.',r'$\qty{200}{ms}$.']),
E('Une distance sonore',r'Un retard de 0,0500 s est mesuré pour un signal dans l’air à 340 m/s.',[r'Calculer la distance parcourue.',r'La même durée donnerait-elle la même distance dans l’eau à 1500 m/s ?'],[r'$d=v\Delta t=340\times0,0500=\qty{17,0}{m}$.',r'Non : $d=1500\times0,0500=\qty{75,0}{m}$.']),
E('Deux microphones',r'Les microphones sont séparés de 1,02 m. Le retard lu vaut 3,00 ms.',[r'Calculer la vitesse du son.',r'Pourquoi comparer le même détail des deux signaux ?'],[r'$v=1,02/(3,00\times10^{-3})=\qty{340}{m.s^{-1}}$.',r'Pour mesurer le retard de la même perturbation, sans confondre deux événements différents.'],'retard-son'),
E('Un obstacle renvoie le son',r'Un écho revient après 0,300 s ; $v=340$ m/s.',[r'Déterminer la longueur du trajet total.',r'Déterminer la distance à l’obstacle.'],[r'$L=340\times0,300=\qty{102}{m}$.',r'$d=L/2=\qty{51,0}{m}$ car le signal effectue l’aller et le retour.'],'echo'),
E('Comparer des vitesses',r'On donne 340 m/s dans l’air et 1500 m/s dans l’eau.',[r'Calculer le rapport des vitesses.',r'Quel signal arrive le premier sur une même distance ?'],[r'$1500/340\simeq4,4$.',r'Le signal dans l’eau arrive plus tôt, si les émissions sont simultanées et les distances égales.']),
E('Une matière qui reste',r'Un son traverse un couloir de 10 m.',[r'Les mêmes molécules d’air partent-elles de la source pour atteindre l’oreille ?',r'Que transmettent-elles de proche en proche ?'],[r'Non. Elles oscillent localement, sans déplacement global sur 10 m.',r'La perturbation mécanique et l’énergie associée.']),
E('Position de la source',r'Deux microphones sont distants de 1,0 m, mais la source n’est pas alignée avec eux.',[r'Peut-on toujours prendre 1,0 m comme différence de trajets ?',r'Quelle disposition simple permet ce choix ?'],[r'Non : le retard dépend de la différence des distances source-microphone, qui peut être plus petite.',r'Aligner source, premier microphone et second microphone, dans cet ordre.']),
E('Améliorer une résolution',r'Le logiciel distingue des retards à 0,1 ms près. Une séparation trop petite donne un retard de 0,2 ms.',[r'Pourquoi la mesure est-elle fragile ?',r'Que peut-on changer sans changer de logiciel ?'],[r'L’incertitude de lecture est importante devant le retard mesuré.',r'Augmenter la séparation dans une géométrie adaptée et limiter les échos parasites, puis répéter.']),
E('Un sonar',r'Un sonar reçoit un retour 0,0800 s après émission. La vitesse du son dans l’eau vaut 1500 m/s.',[r'Calculer la distance à l’objet.',r'Quelle erreur donnerait l’oubli de l’aller-retour ?'],[r'$d=1500\times0,0800/2=\qty{60,0}{m}$.',r'On trouverait 120 m, soit une distance deux fois trop grande.'],'echo'),
E('Un retard mal lu',r'Un premier signal commence à 12,0 ms et le second à 15,0 ms. Les microphones sont séparés de 1,02 m.',[r'Calculer le retard pertinent.',r'Calculer la vitesse et expliquer pourquoi 15,0 ms ne convient pas.'],[r'$\Delta t=15,0-12,0=\qty{3,0}{ms}$.',r'$v=1,02/0,0030=\qty{340}{m.s^{-1}}$. La date de 15,0 ms dépend de l’origine de l’acquisition ; seule la différence des dates décrit le trajet supplémentaire.'])],
E('Une galerie à mesurer',r'Un signal bref est émis à l’entrée d’une galerie rectiligne. Un écho arrive 0,420 s plus tard. On adopte 340 m/s. Une seconde mesure donne 0,424 s.',[r'Estimer la longueur de la galerie avec chaque mesure.',r'Comparer les résultats et citer une cause de différence.',r'Comment vérifier que l’écho étudié provient bien du fond ?'],[r'$d_1=71,4$ m ; $d_2=72,08$ m, soit environ 72,1 m.',r'L’écart est 0,68 m ; la lecture du retard, la position de la source ou la température peuvent contribuer.',r'Comparer les échos à plusieurs positions, repérer un trajet cohérent avec la géométrie et vérifier les réflexions sur les parois.'],'echo',methode=r'Piste 1 : le son parcourt deux longueurs. Piste 2 : comparer sans arrondir trop tôt. Piste 3 : discuter l’origine du signal.',note=r'Une distance sonore dépend du trajet identifié, pas seulement de la formule distance = vitesse fois durée.'),
['Émission, vibration et résonance','Propagation et milieu matériel','Vitesse et mesure dans l’air','Retard, distance et aller-retour'])

C('Période et perception sonore','son',[
'Déterminer une période et une fréquence.',
'Distinguer hauteur, timbre et niveau sonore.',
'Lire une échelle non linéaire et identifier des situations à risque.'],[
('Un motif qui se répète',r'''Un signal périodique présente un motif qui se répète identiquement après une durée minimale $T$, la période. La fréquence $f$ compte le nombre de motifs par seconde.
\begin{loi}$f=1/T$, avec $T$ en secondes et $f$ en hertz. Pour améliorer une lecture graphique, mesurer plusieurs périodes : si cinq périodes durent 10 ms, $T=2,0$ ms et $f=500$ Hz.\end{loi}
\schema{signal-periodique}
Une demi-oscillation n'est pas une période. Choisir deux points dans le même état du motif, par exemple deux maxima successifs.'''),
('Hauteur et timbre',r'''À l'audition humaine, les sons audibles se situent approximativement entre 20 Hz et 20 kHz ; les limites dépendent des personnes. Au-dessous : infrasons ; au-dessus : ultrasons. Dans le domaine audible, une fréquence plus élevée correspond à un son plus aigu.
\schema{timbres}
Deux sons de même fréquence peuvent avoir des formes de signaux différentes, donc des timbres différents. À forme et fréquence comparables, une amplitude plus importante est associée à une intensité sonore plus grande. La fréquence n'est pas une mesure de volume sonore.'''),
('Intensité et niveau',r'''Le niveau d'intensité sonore s'exprime en décibels. Son échelle n'est pas linéaire : on n'additionne pas les niveaux comme des longueurs. Dans les tableaux d'entraînement, une intensité multipliée par 10 correspond à une hausse de niveau de 10 dB ; on utilise cette correspondance fournie sans calcul logarithmique.
\begin{attention}[Exposition sonore]Le risque dépend du niveau et de la durée d'exposition, ainsi que de la proximité de la source. Réduire le niveau, s'éloigner et limiter la durée réduisent l'exposition. Une application de téléphone non étalonnée ne remplace pas une mesure de référence.\end{attention}''')],
r'''\begin{experience}[Enregistrer et comparer]Enregistrer deux instruments jouant la même note à distance constante. Lire plusieurs périodes, comparer fréquence et forme, puis modifier doucement le niveau sans rechercher un son fort. Un microcontrôleur et un petit transducteur peuvent produire un signal de fréquence programmée ; identifier la chaîne commande, vibration, propagation, microphone et acquisition.\end{experience}''',[
E('De la période à la fréquence',r'Un signal a une période de 2,00 ms.',[r'Exprimer $T$ en secondes.',r'Calculer $f$.'],[r'$T=\qty{2,00e-3}{s}$.',r'$f=1/T=\qty{500}{Hz}$.']),
E('De la fréquence à la période',r'Un diapason vibre à 250 Hz.',[r'Calculer sa période.',r'Combien de motifs réalise-t-il en une seconde ?'],[r'$T=1/250=\qty{0,00400}{s}=\qty{4,00}{ms}$.',r'250 motifs en une seconde, par définition du hertz.']),
E('Trois domaines',r'On donne 12 Hz, 1000 Hz et 40 kHz.',[r'Classer ces signaux dans les trois domaines.',r'Le signal de plus grande fréquence est-il nécessairement le plus intense ?'],[r'12 Hz : infrason ; 1000 Hz : domaine audible ; 40 kHz : ultrason.',r'Non. Fréquence et intensité décrivent deux propriétés différentes.']),
E('Lire un motif',r'Utiliser le signal temporel fourni.',[r'Lire la période.',r'En déduire la fréquence.'],[r'Deux maxima successifs sont séparés de 2,0 ms.',r'$f=1/(2,0\times10^{-3})=\qty{500}{Hz}$.'],'signal-periodique'),
E('Mesurer plusieurs périodes',r'Cinq périodes occupent 12,5 ms sur un enregistrement.',[r'Calculer $T$ puis $f$.',r'Pourquoi cette méthode peut-elle améliorer la lecture ?'],[r'$T=12,5/5=\qty{2,50}{ms}$ et $f=\qty{400}{Hz}$.',r'L’incertitude de position des extrémités est répartie sur plusieurs périodes au lieu d’une seule.']),
E('Deux instruments',r'Les signaux A et B de la figure ont la même période.',[r'Comparer leurs hauteurs.',r'Comparer leurs timbres.'],[r'Même période, donc même fréquence et même hauteur perçue si les deux sont audibles.',r'Leurs formes diffèrent : les timbres peuvent être différents.'],'timbres'),
E('Plus aigu',r'Deux sons audibles ont des fréquences de 220 Hz et 660 Hz.',[r'Lequel est plus aigu ?',r'Calculer le rapport des périodes.'],[r'Le son de 660 Hz est plus aigu.',r'$T_{220}/T_{660}=660/220=3$. Le son grave possède la période la plus grande.']),
E('Une échelle en décibels',r'Un tableau indique : intensité $I_0$ : 50 dB ; $10I_0$ : 60 dB ; $100I_0$ : 70 dB.',[r'Que devient l’intensité entre 50 et 70 dB ?',r'Pourquoi 70 dB ne signifie-t-il pas une intensité 1,4 fois celle de 50 dB ?'],[r'Elle est multipliée par 100 d’après le tableau.',r'Le niveau est une grandeur sur une échelle non linéaire ; le rapport 70/50 ne donne pas le rapport des intensités.']),
E('Une confusion de paramètres',r'Une application augmente l’amplitude d’un son enregistré sans changer son motif temporel.',[r'La fréquence change-t-elle ?',r'Quelle sensation peut principalement changer ?'],[r'Non si la période du motif reste identique.',r'Le son peut être perçu plus fort ; sa hauteur reste liée à la même fréquence.']),
E('Un générateur programmé',r'Un programme impose une période de 1,25 ms à un petit transducteur.',[r'Déterminer la fréquence.',r'Proposer la période pour doubler cette fréquence.'],[r'$f=1/0,00125=\qty{800}{Hz}$.',r'Il faut diviser la période par deux : $T=\qty{0,625}{ms}$.']),
E('Un son non périodique',r'Un choc bref est enregistré ; aucun motif répétitif n’est identifiable.',[r'Peut-on utiliser une période unique lue entre deux bosses quelconques ?',r'Pourquoi faut-il d’abord vérifier la répétition ?'],[r'Non : deux bosses ne définissent pas nécessairement un motif répété.',r'La relation $f=1/T$ s’applique ici à un signal périodique ; sans période identifiable, cette lecture serait arbitraire.']),
E('Réduire une exposition',r'Une personne se tient près d’une enceinte pendant un concert.',[r'Citer trois moyens de réduire son exposition sonore.',r'Pourquoi le seul nom du style musical ne permet-il pas de juger le risque ?'],[r'S’éloigner, réduire la durée d’exposition et employer une protection adaptée ; diminuer le niveau à la source est également utile.',r'Le niveau reçu et la durée comptent ; le style ne renseigne pas directement sur ces grandeurs.'])],
E('Une note mal identifiée',r'Un enregistrement montre quatre périodes complètes en 9,09 ms. Un élève mesure seulement la durée entre un maximum et le minimum suivant, puis annonce une fréquence deux fois trop grande.',[r'Calculer la fréquence à partir des quatre périodes.',r'Expliquer l’erreur de l’élève.',r'Un autre instrument joue avec la même période et une autre forme : que peut-on comparer ?'],[r'$T=9,09/4=\qty{2,2725}{ms}$ ; $f\simeq\qty{440}{Hz}$.',r'Pour un signal sinusoïdal, maximum-minimum correspond à une demi-période. Prendre cette durée pour $T$ double $1/T$.',r'Les hauteurs sont identiques, les timbres peuvent différer. L’intensité exige une information sur l’amplitude et la chaîne de mesure.'],methode=r'Piste 1 : diviser la durée totale par quatre. Piste 2 : distinguer oscillation entière et demi-oscillation. Piste 3 : séparer hauteur, timbre et intensité.',note=r'Avant de calculer une fréquence, vérifier le motif complet et l’unité du temps.'),
['Signal périodique, période et fréquence','Domaines audibles, infrasons, ultrasons','Hauteur, timbre, amplitude','Échelle non linéaire des niveaux','Acquisition et production par microcontrôleur'])

C('Lumière et spectres','spectre',[
'Utiliser la propagation rectiligne et la vitesse de la lumière.',
'Distinguer spectre continu et spectre de raies.',
'Caractériser une lumière monochromatique par sa longueur d’onde.'],[
('Des rayons pour modéliser',r'''Dans un milieu transparent et homogène, la lumière se propage en ligne droite. Un rayon représente une direction et un sens de propagation, pas un objet matériel. Pour voir un objet, de la lumière provenant de cet objet doit entrer dans l'œil.
\begin{definition}[Vitesse]Dans le vide, la vitesse de la lumière vaut exactement \qty{299792458}{m.s^{-1}} ; pour les exercices du livre dans le vide ou l'air, $c\simeq\qty{3,00e8}{m.s^{-1}}$. La durée de parcours vaut $\Delta t=d/c$.\end{definition}
La lumière parcourt environ un mètre en quelques nanosecondes ; elle est beaucoup plus rapide que le son dans l'air.'''),
('Décomposer une lumière',r'''Un prisme ou un réseau sépare les radiations d'une lumière polychromatique : on obtient un spectre. Une radiation monochromatique est caractérisée par sa longueur d'onde dans le vide ou l'air, souvent exprimée en nanomètres. Le visible s'étend approximativement de 400 à 800 nm selon les conventions et la sensibilité de l'œil.
\schema{spectres}
\begin{propriete}[Corps chaud]Un corps chaud dense émet un spectre continu. Quand sa température augmente, le spectre s'enrichit vers les courtes longueurs d'onde du visible ; la couleur apparente évolue. Une source gazeuse excitée peut présenter un spectre de raies caractéristique des espèces présentes.\end{propriete}'''),
('Identifier par des raies',r'''Pour exploiter un spectre, comparer les positions des raies à celles de références avec la même échelle de longueurs d'onde. Une seule raie commune ne suffit pas toujours à identifier une espèce ; rechercher un ensemble cohérent.
\begin{savoirfaire}[Méthode]Lire les unités, relever plusieurs longueurs d'onde, comparer aux valeurs de référence, puis formuler une conclusion avec la précision de lecture. Un spectre schématique sans axe gradué ne permet pas une lecture numérique précise.\end{savoirfaire}
Une lumière colorée peut être monochromatique ou résulter de plusieurs radiations ; la couleur apparente seule ne donne pas la composition spectrale.''')],
r'''\begin{experience}[Observer un spectre]Observer avec un spectroscope une lampe adaptée puis une source à raies sous encadrement. Comparer les spectres, repérer continu ou discontinu, relever l'échelle. Ne jamais regarder directement le Soleil ni un faisceau laser. Pour une mesure numérique, vérifier l'étalonnage en longueur d'onde.\end{experience}''',[
E('Une valeur à connaître',r'On utilise la vitesse de la lumière dans l’air pour un calcul scolaire.',[r'Donner sa valeur approchée en SI.',r'La comparer qualitativement à 340 m/s.'],[r'$c\simeq\qty{3,00e8}{m.s^{-1}}$.',r'Elle est près de neuf cent mille fois plus grande que la vitesse du son dans l’air.']),
E('Des nanomètres aux mètres',r'Une radiation a pour longueur d’onde 550 nm.',[r'Exprimer cette valeur en mètres.',r'Le nanomètre désigne-t-il une durée ?'],[r'$\lambda=\qty{5,50e-7}{m}$.',r'Non, c’est une unité de longueur, égale à $10^{-9}$ m.']),
E('Continuité du spectre',r'La figure compare une bande continue et un ensemble de raies.',[r'Associer les deux types de spectres.',r'Lequel peut correspondre à un corps chaud dense ?'],[r'La bande couvrant sans interruption un intervalle est continue ; les traits séparés constituent un spectre de raies.',r'Le spectre continu.'],'spectres'),
E('Un trajet lumineux',r'Une impulsion lumineuse parcourt 900 m dans l’air ; $c=3,00\times10^8$ m/s.',[r'Calculer sa durée de propagation.',r'Exprimer la durée en microsecondes.'],[r'$\Delta t=900/(3,00\times10^8)=\qty{3,00e-6}{s}$.',r'$\qty{3,00}{\micro s}$.']),
E('Reconnaître des raies',r'La source X possède des raies à 450, 520 et 650 nm. Les références sont A : 450, 520, 650 nm ; B : 430, 550, 680 nm.',[r'Quelle référence correspond à X ?',r'Pourquoi comparer plusieurs raies ?'],[r'A présente le même ensemble de raies à la précision annoncée.',r'Une coïncidence isolée peut être fortuite ou commune à plusieurs espèces ; l’ensemble renforce l’identification.']),
E('Chauffer davantage',r'Un filament chaud passe d’une lueur rouge à une lumière plus blanche.',[r'Comment évolue qualitativement son spectre visible ?',r'Faut-il un spectre de raies pour expliquer cette évolution ?'],[r'Il s’enrichit vers les radiations de plus courtes longueurs d’onde du visible.',r'Non : un filament dense chaud présente un spectre continu.']),
E('Monochromatique ou non',r'Une source verte possède deux raies à 530 et 550 nm.',[r'Est-elle monochromatique ?',r'La couleur verte suffit-elle à donner une seule longueur d’onde ?'],[r'Non, elle émet deux radiations distinctes.',r'Non : plusieurs compositions peuvent produire une couleur apparente voisine.']),
E('Voir un objet',r'Un livre est éclairé dans une salle.',[r'Quel trajet de lumière permet sa vision ?',r'L’œil doit-il envoyer un rayon vers le livre ?'],[r'De la lumière de la source est diffusée par le livre puis pénètre dans l’œil.',r'Non, la vision résulte de lumière reçue par l’œil.']),
E('Une distance astronomique',r'La lumière d’une source met 500 s pour nous parvenir ; $c=3,00\times10^8$ m/s.',[r'Calculer la distance.',r'Exprimer cette distance en kilomètres.'],[r'$d=c\Delta t=\qty{1,50e11}{m}$.',r'$\qty{1,50e8}{km}$. L’observation nous renseigne sur l’état de la source 500 s plus tôt.']),
E('Un aller-retour lumineux',r'Un télémètre reçoit une impulsion réfléchie après 40,0 ns. On adopte $c=3,00\times10^8$ m/s.',[r'Calculer la distance à la cible.',r'Pourquoi diviser par deux ?'],[r'$d=c\Delta t/2=3,00\times10^8\times40,0\times10^{-9}/2=\qty{6,00}{m}$.',r'La durée mesurée couvre l’aller jusqu’à la cible puis le retour au récepteur.']),
E('La lecture d’un mélange',r'Un spectre contient toutes les raies de A et deux raies supplémentaires absentes de A.',[r'Quelle présence est compatible avec le spectre ?',r'Peut-on affirmer que la source contient seulement A ?'],[r'La présence de A est compatible avec les raies observées.',r'Non : les raies supplémentaires suggèrent une autre espèce ou demandent une explication expérimentale.']),
E('Éclair et tonnerre',r'Un éclair est vu puis le tonnerre est entendu 3,0 s plus tard. $v_s=340$ m/s.',[r'Estimer la distance en négligeant le temps lumineux.',r'Justifier cette approximation à partir de l’ordre de grandeur.'],[r'$d\simeq340\times3,0=\qty{1020}{m}$, soit environ 1,0 km.',r'La lumière parcourt cette distance en environ 3,4 microsecondes, négligeables devant 3,0 s.'])],
E('Identifier un éclairage',r'Une lampe présente trois raies à 450, 520 et 650 nm sur un faible fond continu. Une autre lampe produit un spectre continu plus riche vers le bleu lorsqu’on augmente son chauffage.',[r'Comparer les deux mécanismes d’émission proposés par les observations.',r'La première lampe est-elle monochromatique ?',r'Quelle information supplémentaire permettrait d’identifier l’espèce responsable des raies ?'],[r'La première montre une émission de raies sur un fond ; la seconde est compatible avec un corps chaud dense dont la température augmente.',r'Non : au moins trois radiations sont présentes, en plus du fond.',r'Une table de spectres de référence et une échelle étalonnée permettraient de comparer plusieurs raies, avec la précision de mesure.'],methode=r'Piste 1 : séparer fond et raies. Piste 2 : compter les radiations. Piste 3 : chercher une référence physique.',note=r'La couleur apparente ne remplace pas l’analyse de la composition spectrale.'),
['Propagation rectiligne et c','Longueur d’onde monochromatique','Spectre thermique continu','Spectres de raies et identification'])

C('Réflexion et réfraction','lunette',[
'Mesurer les angles par rapport à la normale.',
'Appliquer les lois de Snell-Descartes.',
'Déterminer un indice et expliquer la dispersion.'],[
('À l’interface entre deux milieux',r'''Une partie de la lumière peut être réfléchie, une autre transmise avec un changement de direction : la réfraction. La normale est la droite perpendiculaire à l'interface au point d'incidence. Tous les angles des lois suivantes sont mesurés avec cette normale.
\schema{refraction}
\begin{loi}[Réflexion]Le rayon réfléchi reste dans le plan d'incidence et l'angle de réflexion est égal à l'angle d'incidence : $i'=i$.\end{loi}\schema{reflexion}'''),
('L’indice et la réfraction',r'''\begin{loi}[Snell-Descartes]Les rayons incident, réfracté et la normale sont dans le même plan ; $n_1\sin i=n_2\sin r$. L'indice $n$ est sans unité. On prend généralement $n_{\mathrm{air}}\simeq1,00$.\end{loi}
Si la lumière entre dans un milieu d'indice plus élevé, elle se rapproche de la normale : $r<i$. Pour trouver un angle, utiliser la fonction inverse du sinus et vérifier le mode degré de la calculatrice.
\begin{exemple}De l'air vers un verre d'indice 1,50 avec $i=30,0^\circ$, $\sin r=\sin30^\circ/1,50=1/3$ ; $r\simeq19,5^\circ$.\end{exemple}'''),
('Mesures et dispersion',r'''Pour une série de mesures air-milieu, tracer $\sin i$ en fonction de $\sin r$. Si le modèle convient, les points se regroupent près d'une droite passant par l'origine, de pente $n_{\mathrm{milieu}}/n_{\mathrm{air}}$.
\schema{snell-graphe}
L'indice d'un matériau dispersif varie avec la longueur d'onde. Un prisme dévie alors différemment les radiations et décompose une lumière blanche. Un réseau peut également produire un spectre, par un mécanisme différent qui n'est pas détaillé ici. Un prisme ne crée pas les radiations : il les sépare.
\schema{prisme}''')],
r'''\begin{experience}[Tester une loi]Diriger un faisceau adapté vers une surface plane transparente, repérer normale et point d'incidence, mesurer $i$, $i'$ et $r$ pour plusieurs positions. Tracer les sinus, rechercher la proportionnalité et estimer l'indice. Éviter toute exposition des yeux au faisceau ou à sa réflexion.\end{experience}''',[
E('La bonne référence angulaire',r'Un rayon incident fait 35° avec la normale.',[r'Donner l’angle d’incidence.',r'Donner l’angle qu’il fait avec la surface.'],[r'$i=35^\circ$.',r'$90-35=55^\circ$. La surface et la normale sont perpendiculaires.']),
E('Réfléchir un rayon',r'L’angle d’incidence vaut 40°.',[r'Donner l’angle de réflexion.',r'Situer le rayon réfléchi par rapport à la normale.'],[r"$i'=40^\circ$ par la loi de réflexion.",r'Il est de l’autre côté de la normale que le rayon incident, dans le plan d’incidence.'],'reflexion'),
E('Lire un indice',r'Un verre a un indice 1,50 et l’air un indice proche de 1,00.',[r'L’indice a-t-il une unité ?',r'À l’entrée dans le verre, le rayon se rapproche-t-il de la normale ?'],[r'Non, l’indice est sans unité.',r'Oui pour une incidence non nulle : le milieu d’arrivée a l’indice le plus élevé.']),
E('Une incidence normale',r'Un rayon arrive perpendiculairement à une interface.',[r'Que vaut $i$ ?',r'Que donne la loi de réfraction pour $r$ ?'],[r'$i=0^\circ$ car le rayon suit la normale.',r'$\sin r=0$, donc $r=0^\circ$ : le rayon transmis n’est pas dévié.']),
E('Calculer un angle réfracté',r'De l’air ($n_1=1,00$) vers le verre ($n_2=1,50$), $i=30,0^\circ$.',[r'Calculer $\sin r$.',r'Déterminer $r$ et contrôler le sens de déviation.'],[r'$\sin r=(1,00/1,50)\sin30,0^\circ=0,3333\ldots$.',r'$r\simeq19,5^\circ<i$ : le rayon se rapproche de la normale.'],'refraction'),
E('Retrouver un indice',r'Un rayon venant de l’air donne $i=45,0^\circ$ et $r=28,1^\circ$.',[r'Exprimer l’indice du matériau.',r'Calculer sa valeur approchée.'],[r'$n=\sin i/\sin r$ avec l’indice de l’air pris égal à 1.',r'$n=\sin45,0^\circ/\sin28,1^\circ\simeq1,50$.']),
E('Lire une droite de sinus',r'Le graphique porte $\sin i$ verticalement et $\sin r$ horizontalement pour une entrée depuis l’air.',[r'Déterminer la pente de la droite.',r'En déduire l’indice du milieu.'],[r'Par exemple, le point $(0,40;0,60)$ donne une pente de $0,60/0,40=1,50$.',r'$n\simeq1,50$ car la pente vaut $n/n_{\mathrm{air}}$.'],'snell-graphe'),
E('Pourquoi un prisme disperse',r'Le verre d’un prisme possède un indice légèrement différent pour le rouge et le violet.',[r'Pourquoi les deux radiations ne sortent-elles pas dans la même direction ?',r'Le prisme transforme-t-il une radiation rouge en radiation violette ?'],[r'Les lois de réfraction donnent des déviations différentes lorsque les indices diffèrent.',r'Non : il sépare les radiations présentes dans la lumière incidente.'],'prisme'),
E('Une sortie vers l’air',r'Un rayon passe d’un verre d’indice 1,50 à l’air avec $i=20,0^\circ$.',[r'Calculer $\sin r$ puis $r$.',r'Le rayon s’éloigne-t-il de la normale ?'],[r'$\sin r=1,50\sin20,0^\circ\simeq0,513$ ; $r\simeq30,9^\circ$.',r'Oui : $r>i$, cohérent avec le passage vers l’indice plus faible.']),
E('Une pente inversée',r'Un groupe trace $\sin r$ en fonction de $\sin i$ et trouve une pente 0,667 pour un passage air-verre.',[r'Pourquoi cette pente n’est-elle pas directement l’indice du verre ?',r'En déduire l’indice.'],[r'Les axes sont inversés par rapport au graphique précédent : la pente vaut $n_{\mathrm{air}}/n_{\mathrm{verre}}$.',r'$n_{\mathrm{verre}}\simeq1/0,667\simeq1,50$.']),
E('Un angle impossible',r'Pour un passage d’un milieu d’indice 1,50 vers l’air, un calcul conduit à $\sin r=1,15$.',[r'Pourquoi aucun angle réfracté réel ne correspond-il ?',r'Que doit-on conclure sur le modèle de rayon transmis pour cette incidence ?'],[r'Le sinus d’un angle réel est compris entre -1 et 1.',r'Aucun rayon réfracté propagatif ne satisfait cette équation : on rencontre la réflexion totale. Cette situation est un prolongement guidé, pas une nouvelle formule à mémoriser.']),
E('Tester une série',r'Pour une entrée depuis l’air, les couples $(\sin r;\sin i)$ mesurés sont $(0,10;0,15)$, $(0,20;0,30)$ et $(0,30;0,46)$.',[r'Comparer les rapports $\sin i/\sin r$.',r'Une petite différence suffit-elle à rejeter la loi ?'],[r'Les rapports valent 1,50 ; 1,50 ; environ 1,53. Ils sont proches.',r'Non : il faut comparer les écarts à la précision des mesures et du tracé, et rechercher des erreurs systématiques.'])],
E('Deux couleurs dans le verre',r'Un faisceau arrive de l’air sous $i=40,0^\circ$. Le verre a pour indices $n_R=1,50$ pour le rouge et $n_V=1,53$ pour le violet.',[r'Calculer les deux angles réfractés.',r'Quelle radiation se rapproche le plus de la normale à cette interface ?',r'Pourquoi une différence faible peut-elle devenir visible après le prisme ?'],[r'$r_R=\arcsin(\sin40^\circ/1,50)\simeq25,4^\circ$ ; $r_V\simeq24,8^\circ$.',r'Le violet, car son angle avec la normale est plus petit.',r'Les directions de sortie diffèrent après les deux interfaces ; à distance, la séparation spatiale peut devenir observable.'],methode=r'Piste 1 : appliquer la loi à chaque indice. Piste 2 : comparer les angles à la normale. Piste 3 : distinguer angle et séparation sur l’écran.',note=r'La dispersion s’explique par une dépendance de l’indice à la longueur d’onde.'),
['Réflexion et réfraction, plan d’incidence','Angles à la normale','Loi de Snell-Descartes','Détermination expérimentale d’un indice','Dispersion par prisme et réseau'])

C('Lentilles et vision','lunette',[
'Identifier centre optique, foyers et distance focale.',
'Construire une image réelle avec des rayons remarquables.',
'Déterminer un grandissement et modéliser l’œil.'],[
('Une lentille mince convergente',r'''Une lentille convergente dévie un faisceau parallèle à l'axe optique vers son foyer image $F^{\prime}$. Son centre optique est O ; les foyers F et $F^{\prime}$ sont symétriques par rapport à O. La distance focale $f'$ est la distance positive $OF^{\prime}$.
\schema{lentille-foyers}
\begin{propriete}[Trois rayons utiles]Un rayon passant par O n'est pas dévié dans le modèle de la lentille mince. Un rayon incident parallèle à l'axe ressort en passant par $F^{\prime}$. Un rayon passant par F ressort parallèle à l'axe.\end{propriete}'''),
('Construire une image réelle',r'''Pour un objet AB perpendiculaire à l'axe, avec A sur l'axe et placé avant le foyer objet, tracer au moins deux rayons issus de B. Leur intersection après la lentille donne $B^{\prime}$ ; $A^{\prime}$ est le pied sur l'axe. Tous les rayons issus de B et transmis dans le modèle convergent en $B^{\prime}$, pas seulement les deux rayons tracés.
\schema{lentille-2f}
Une image réelle peut être recueillie sur un écran placé dans son plan. Elle est ici renversée. Si l'objet est trop près de la lentille, la construction d'une image réelle sur écran n'est plus possible : le cas de la loupe constitue un autre contexte.'''),
('Grandissement et œil réduit',r'''Le grandissement algébrique est $\gamma=\overline{A^{\prime}B^{\prime}}/\overline{AB}$ : il est négatif pour l'image renversée. Sa valeur absolue compare les tailles. Par Thalès, pour les longueurs positives objet-lentille $p$ et lentille-image $p^{\prime}$, $|\gamma|=p^{\prime}/p$ dans cette construction.
\schema{oeil}
L'œil réduit associe un diaphragme à la pupille, une lentille convergente à l'ensemble optique cornée-cristallin, et un écran à la rétine. L'image nette se forme sur la rétine. L'accommodation modifie la convergence du système optique ; le cerveau interprète l'image reçue.''')],
r'''\begin{experience}[Former une image]Aligner un objet lumineux adapté, une lentille et un écran sur un banc. Repérer la distance focale avec un objet lointain, puis placer l'objet au-delà de F. Déplacer l'écran jusqu'à la netteté ; mesurer tailles et distances, comparer la construction et le grandissement. Ne jamais viser le Soleil.\end{experience}
\begin{savoirfaire}[Un dessin exploitable]Indiquer l'échelle spatiale, O, F, $F^{\prime}$, AB, l'axe et le sens de propagation. Les flèches des rayons indiquent la propagation ; les flèches de AB et $A^{\prime}B^{\prime}$ indiquent l'orientation de l'objet et de l'image.\end{savoirfaire}''',[
E('Repérer les foyers',r'La lentille a une distance focale de 10 cm.',[r'À quelle distance de O placer F et $F^{\prime}$ ?',r'Quel foyer reçoit les rayons arrivant parallèlement à l’axe ?'],[r'À 10 cm de part et d’autre de O, sur l’axe optique.',r'Le foyer image $F^{\prime}$, du côté de sortie de la lumière.'],'lentille-foyers'),
E('Le rayon central',r'Un rayon passe par le centre optique O.',[r'Comment le tracer après la lentille dans le modèle mince ?',r'Ce rayon suffit-il à localiser seul l’image d’un point ?'],[r'On le prolonge en ligne droite, sans déviation.',r'Non : il faut au moins une autre direction de rayon pour déterminer leur intersection.']),
E('Un rayon parallèle',r'Un rayon issu de B atteint la lentille parallèlement à l’axe.',[r'Par quel point passe le rayon émergent ?',r'Quel rayon émergent serait parallèle à l’axe ?'],[r'Par le foyer image $F^{\prime}$.',r'Un rayon incident qui passe par le foyer objet F ressort parallèle à l’axe.']),
E('Lire une image réelle',r'Un objet de 2,0 cm placé à 20 cm d’une lentille de focale 10 cm est représenté à l’échelle indiquée.',[r'Construire l’image avec deux rayons.',r'Donner sa position, sa taille et son sens.'],[r'Le rayon central et le rayon parallèle réfracté par $F^{\prime}$ se coupent à droite ; la version corrigée montre la construction.',r'L’image est à 20 cm de O, de taille 2,0 cm, renversée.'],'lentille-2f'),
E('Un grandissement',r'Un objet de 3,0 cm donne une image renversée de 1,5 cm.',[r'Calculer le grandissement algébrique.',r'L’image est-elle agrandie ou réduite ?'],[r'$\gamma=-1,5/3,0=-0,50$.',r'Elle est réduite car $|\gamma|=0,50<1$.']),
E('Construire une image réduite',r'La focale vaut 10 cm, l’objet est à 30 cm de O et mesure 2,0 cm. La figure est à l’échelle.',[r'Construire et lire la position de l’image.',r'Lire sa taille et calculer $\gamma$.'],[r'Les rayons se coupent à 15 cm après la lentille.',r'L’image mesure 1,0 cm et est renversée : $\gamma=-1,0/2,0=-0,50$.'],'lentille-3f'),
E('Le modèle de l’œil',r'Utiliser le schéma de l’œil réduit.',[r'Associer pupille, cristallin et rétine aux trois éléments du modèle.',r'Où doit se former l’image pour une vision nette ?'],[r'Pupille : diaphragme ; système cornée-cristallin : lentille ; rétine : écran.',r'Dans le plan de la rétine.'],'oeil'),
E('Utiliser Thalès',r'Une image réelle est à 24 cm d’une lentille ; l’objet est à 12 cm et mesure 1,0 cm.',[r'Déterminer $|\gamma|$.',r'Donner la taille et le sens de l’image.'],[r'$|\gamma|=p^{\prime}/p=24/12=2,0$.',r'La taille vaut 2,0 cm et l’image réelle d’un objet réel dans ce montage est renversée.']),
E('Un écran mal placé',r'Une image nette devrait se former à 15 cm après la lentille ; l’écran est à 20 cm.',[r'Pourquoi l’image observée est-elle floue ?',r'Doit-on changer la position de l’écran pour ce montage fixe ?'],[r'Les rayons d’un même point ne se rejoignent pas dans le plan actuel de l’écran.',r'Oui : rapprocher l’écran de la lentille jusqu’au plan de l’image, sans modifier les autres positions.']),
E('Cacher une moitié',r'On masque une moitié de la lentille, sans déplacer le montage.',[r'Une moitié de l’image disparaît-elle nécessairement ?',r'Quel effet principal peut-on attendre sur la luminosité ?'],[r'Non. Chaque point de l’image peut encore recevoir des rayons passant par la partie libre de la lentille, si elle les laisse passer.',r'L’image devient moins lumineuse car moins de lumière est transmise.']),
E('Une accommodation',r'Un objet se rapproche de l’œil alors que la distance entre le système optique et la rétine reste pratiquement fixe.',[r'Quelle propriété l’œil peut-il modifier pour garder une image nette ?',r'Le modèle demande-t-il de déplacer la rétine comme un écran de banc ?'],[r'Il modifie sa convergence par accommodation, principalement grâce au cristallin.',r'Non : l’analogie avec le banc aide à comprendre, mais l’œil ne déplace pas sa rétine pour faire la mise au point.']),
E('Valider un tracé',r'Un dessin place l’objet à 30 cm, l’image à 15 cm, et donne $|\gamma|=2$.',[r'Détecter l’incohérence avec Thalès.',r'Quelle valeur doit-on obtenir pour une image réelle renversée ?'],[r'$p^{\prime}/p=15/30=0,50$, et non 2. Les distances ont été inversées dans le quotient.',r'$\gamma=-0,50$. Le signe traduit le renversement.'])],
E('Choisir la place de l’écran',r'Un objet de 2,0 cm est placé à 30 cm d’une lentille de focale 10 cm. Un élève veut une image nette sur un écran situé à 15 cm de la lentille.',[r'Construire l’image et vérifier la proposition.',r'Calculer le grandissement par deux méthodes.',r'Expliquer pourquoi les rayons tracés ne sont pas les seuls qui contribuent à l’image.'],[r'La construction donne une image à 15 cm : la position proposée convient.',r'Par les tailles : $\gamma=-1,0/2,0=-0,50$ ; par Thalès : $|\gamma|=15/30=0,50$, avec le signe négatif du renversement.',r'Tous les rayons issus de chaque point et traversant la lentille idéale convergent au point image associé. Les rayons remarquables servent seulement à localiser cette intersection.'],'lentille-3f',methode=r'Piste 1 : construire deux rayons issus du sommet. Piste 2 : utiliser les échelles et Thalès. Piste 3 : distinguer construction et faisceau réel.',note=r'Une image se construit point par point ; deux rayons remarquables localisent chaque point image.'),
['Lentille convergente, foyers et focale','Construction d’une image réelle','Grandissement et Thalès','Modèle de l’œil réduit','Formation expérimentale d’une image'])

C('Circuits et lois électriques','piles',[
'Mesurer intensité et tension avec les branchements adaptés.',
'Appliquer les lois des nœuds et des mailles.',
'Tracer une caractéristique et exploiter la loi d’Ohm.'],[
('Deux grandeurs distinctes',r'''L'intensité mesure le débit de charge à travers une section du circuit ; la tension compare les potentiels de deux points. Un ampèremètre se branche en série dans la branche étudiée. Un voltmètre se branche en dérivation entre les deux points. Un courant conventionnel sort de la borne positive du générateur dans le circuit extérieur.
\schema{mesures-circuit}
On note $U_{AB}=V_A-V_B$ : inverser les bornes change le signe. Pour une mesure positive, les entrées et les polarités du multimètre doivent correspondre au sens choisi.'''),
('Nœuds et mailles',r'''\begin{loi}[Loi des nœuds]La somme des intensités entrant dans un nœud égale celle des intensités qui en sortent. Des signes peuvent être utilisés si les flèches ont été choisies arbitrairement.\end{loi}
\schema{noeud}
\begin{loi}[Loi des mailles]La somme algébrique des tensions dans une maille est nulle. Dans un circuit série simple, $U_G=U_1+U_2$ avec les polarités indiquées. Deux dipôles branchés entre les mêmes nœuds ont la même tension.\end{loi}
L'intensité ne se consomme pas dans une résistance. La description doit distinguer la circulation de charge et les transferts d'énergie.'''),
('Caractéristique d’un dipôle',r'''Une caractéristique relie une tension à une intensité avec des conventions précisées. Pour un conducteur ohmique dans les conditions étudiées, les points $U=f(I)$ se répartissent près d'une droite passant par l'origine.
\begin{loi}[Loi d'Ohm]En convention récepteur, $U=RI$, avec $U$ en volts, $I$ en ampères et $R$ en ohms. La pente de $U=f(I)$ donne $R$ si l'intensité est en ampères.\end{loi}
\schema{ohm}
Le point de fonctionnement correspond à un couple $(I;U)$ compatible avec le dipôle et l'alimentation. Tout dipôle n'est pas ohmique : une courbe qui ne passe pas par l'origine ou qui n'est pas droite ne peut pas être résumée par une résistance constante.''')],
r'''\begin{experience}[Relever une caractéristique]Utiliser une alimentation scolaire de très basse tension continue. Varier doucement la tension, relever U en dérivation et I en série, sans dépasser les caractéristiques des composants. Tracer U en fonction de I, convertir les milliampères en ampères avant de calculer la pente. Couper l'alimentation avant de modifier un branchement ; ne jamais relier un ampèremètre seul aux bornes du générateur.\end{experience}''',[
E('Choisir le branchement',r'On veut mesurer la tension d’une résistance et l’intensité qui la traverse.',[r'Placer voltmètre et ampèremètre.',r'Quel branchement dangereux faut-il éviter pour l’ampèremètre ?'],[r'Voltmètre en dérivation sur la résistance ; ampèremètre en série avec elle.',r'Le brancher directement entre les bornes du générateur : il pourrait créer un court-circuit.'],'mesures-circuit'),
E('Convertir une intensité',r'Un courant a une intensité de 25,0 mA.',[r'Exprimer I en ampères.',r'Calculer U pour $R=200\,\Omega$.'],[r'$I=\qty{0,0250}{A}$.',r'$U=RI=200\times0,0250=\qty{5,00}{V}$.']),
E('Une dérivation',r'Un courant de 0,30 A se sépare en deux branches ; la première reçoit 0,12 A.',[r'Calculer le courant de la seconde branche.',r'Citer la loi utilisée.'],[r'$I_2=0,30-0,12=\qty{0,18}{A}$.',r'Loi des nœuds : les intensités entrantes et sortantes s’équilibrent.'],'noeud'),
E('Une maille simple',r'Un générateur de 9,0 V alimente deux dipôles en série. Le premier a une tension de 3,5 V.',[r'Déterminer la tension du second.',r'La tension est-elle nécessairement la même sur les deux ?'],[r'$U_2=9,0-3,5=\qty{5,5}{V}$.',r'Non. En série, les tensions s’ajoutent ; leurs valeurs dépendent des dipôles.']),
E('Une caractéristique ohmique',r'Lire la caractéristique U=f(I) fournie.',[r'Déterminer la résistance.',r'Lire U pour $I=20$ mA.'],[r'Par exemple $R=4,0/0,020=\qty{200}{\ohm}$. Il faut convertir les mA en A.',r'$U=\qty{4,0}{V}$.'],'ohm'),
E('Résistance inconnue',r'Une tension de 6,0 V produit une intensité de 15 mA dans un conducteur ohmique.',[r'Calculer R.',r'Quelle intensité prévoir à 3,0 V si R reste constant ?'],[r'$R=6,0/0,015=\qty{400}{\ohm}$.',r'$I=3,0/400=\qty{0,0075}{A}=\qty{7,5}{mA}$.']),
E('Deux branches parallèles',r'Deux résistances de 100 et 200 ohms sont branchées chacune sous 6,0 V.',[r'Calculer les intensités des branches.',r'Calculer l’intensité totale.'],[r'$I_1=6,0/100=60$ mA et $I_2=6,0/200=30$ mA.',r'$I=I_1+I_2=\qty{90}{mA}$.']),
E('Inverser les bornes',r'Un voltmètre affiche $U_{AB}=+4,2$ V.',[r'Quelle valeur donnerait $U_{BA}$ ?',r'Le changement de signe indique-t-il une panne ?'],[r'$U_{BA}=-U_{AB}=\qty{-4,2}{V}$.',r'Non : il traduit l’inversion du choix des bornes de mesure.']),
E('Deux résistances en série',r'Un générateur idéal de 9,0 V alimente en série $R_1=100\,\Omega$ et $R_2=200\,\Omega$.',[r'Exprimer I avec la loi des mailles et la loi d’Ohm.',r'Calculer I, $U_1$ et $U_2$.'],[r'$9,0=R_1I+R_2I=(R_1+R_2)I$.',r'$I=9,0/300=\qty{0,030}{A}$ ; $U_1=3,0$ V et $U_2=6,0$ V.'],'serie'),
E('Un courant non consommé',r'Un ampèremètre mesure 20 mA avant une résistance dans une unique boucle.',[r'Quelle intensité doit-on mesurer après elle en régime établi ?',r'Pourquoi « la résistance consomme le courant » est-il incorrect ?'],[r'20 mA : l’intensité est la même dans tous les dipôles de cette branche série.',r'La charge ne disparaît pas ; la résistance est le siège de transferts d’énergie, ce qui est une autre description.']),
E('Un dipôle non ohmique',r'Les couples $(I;U)$ sont (10 mA ; 1,0 V), (20 mA ; 2,8 V) et (30 mA ; 5,5 V).',[r'Comparer les quotients U/I.',r'Le modèle d’une résistance constante convient-il ?'],[r'100 ; 140 ; environ 183 ohms : les quotients ne sont pas constants.',r'Non sur cette gamme : la tension n’est pas proportionnelle à l’intensité.']),
E('Une modélisation numérique',r'Un ajustement donne $U=198I+0,02$ avec U en V et I en A. Les écarts expérimentaux sont de l’ordre de 0,03 V.',[r'Quelle résistance approchée suggère la pente ?',r'Peut-on considérer le petit décalage comme nécessairement significatif ?'],[r'Une résistance d’environ 198 ohms.',r'Non : 0,02 V est de l’ordre des écarts de mesure. Examiner les données et l’étalonnage avant de rejeter le passage par l’origine.'])],
E('Un circuit à diagnostiquer',r'Une alimentation idéale de 6,0 V dessert deux branches en dérivation : $R_1=200\,\Omega$ et $R_2=300\,\Omega$. Un ampèremètre principal indique 50 mA.',[r'Calculer les intensités attendues dans les deux branches.',r'Comparer l’intensité totale prévue à la mesure.',r'Un élève propose de placer l’ampèremètre directement sur le générateur pour confirmer : corriger sa proposition.'],[r'$I_1=6,0/200=30$ mA et $I_2=6,0/300=20$ mA.',r'$I=30+20=\qty{50}{mA}$ : l’indication est cohérente.',r'L’ampèremètre doit être en série dans la branche principale. Le placer seul en dérivation sur le générateur créerait un risque de court-circuit.'],methode=r'Piste 1 : même tension dans les branches. Piste 2 : appliquer Ohm puis la loi des nœuds. Piste 3 : vérifier le branchement du multimètre.',note=r'Une mesure électrique demande à la fois une loi adaptée et un branchement correct.'),
['Mesurer tension et intensité','Lois des nœuds et des mailles, au plus deux mailles','Loi d’Ohm','Caractéristique et point de fonctionnement','Nuage de points et modélisation Python'])

C('Capteurs et outils numériques','mesure',[
'Relier une grandeur physique à la réponse d’un capteur.',
'Construire et utiliser une courbe d’étalonnage.',
'Exploiter un capteur avec un microcontrôleur.'],[
('Une grandeur devient un signal',r'''Un capteur répond à une grandeur d'intérêt : température, éclairement, pression. Un capteur résistif fait varier sa résistance ; le circuit associé transforme cette variation en tension mesurable. Une thermistance peut voir sa résistance diminuer quand la température augmente ; une photorésistance dépend de l'éclairement. Le comportement exact doit être étalonné.
\schema{capteur-courbe}
La chaîne de mesure comprend la grandeur, le capteur, le conditionnement électrique, l'acquisition puis l'affichage ou le traitement. Une tension lue ne donne pas seule une température sans relation d'étalonnage.'''),
('Étalonner et interpoler',r'''Mesurer simultanément la grandeur avec une référence et la résistance du capteur. Tracer les couples et choisir un modèle sur le domaine testé. Sur l'exemple construit de ce chapitre, entre 0 et 40 °C, $R(\mathrm{k}\Omega)=20,0-0,400\theta(^{\circ}\mathrm C)$. Cette relation est une donnée de modèle locale, pas une loi universelle des thermistances.
\begin{savoirfaire}[Interpolation]Pour $R=\qty{10,0}{k\ohm}$, $\theta=(20,0-10,0)/0,400=25,0\,^{\circ}\mathrm C$. Toujours vérifier que la valeur se situe dans le domaine d'étalonnage. Une courbe non linéaire exige une lecture ou un modèle adaptés.\end{savoirfaire}'''),
('Du circuit au programme',r'''On peut alimenter deux résistances en série et mesurer la tension aux bornes de l'une d'elles. Le courant dans les deux est le même, et la loi des mailles relie leurs tensions à la tension d'alimentation. L'entrée de mesure est supposée ici ne pas prélever de courant significatif.
\schema{pont-capteur}
Pour le montage, $U=U_0R_c/(R_0+R_c)$. Cette relation se retrouve par les lois du chapitre précédent. Un convertisseur analogique-numérique renvoie un entier associé à la tension ; le programme convertit cet entier puis applique l'étalonnage. Les limites d'entrée et la référence de tension dépendent du matériel.''')],
r'''\begin{experience}[Un capteur résistif]Sous encadrement, relever la résistance d'une thermistance à plusieurs températures mesurées par un thermomètre de référence ; attendre la stabilisation. Construire la courbe puis déterminer une température inconnue. Associer ensuite le capteur à une carte selon sa documentation et vérifier que la tension admissible n'est jamais dépassée.\end{experience}
\begin{docu}{1}{Traitement d'une acquisition simulée}
Le convertisseur fictif de l'exemple renvoie 0 pour 0 V et 1000 pour 5,00 V. Il ne décrit pas une carte commerciale particulière.
\begin{verbatim}
code = 400
u = 5.00 * code / 1000
r0 = 10000
rc = r0 * u / (5.00 - u)
print(rc)  # resistance en ohms
\end{verbatim}
Tester les bornes et les dénominateurs avant d'utiliser un programme sur des mesures réelles.
\end{docu}''',[
E('Reconnaître un capteur',r'Un téléphone ajuste sa luminosité et affiche sa température interne.',[r'Quelles grandeurs des capteurs peuvent-ils détecter ?',r'Un capteur résistif fournit-il directement une phrase à l’écran ?'],[r'Un capteur peut détecter l’éclairement ; un autre la température.',r'Non : sa réponse physique est convertie, acquise et traitée avant affichage.']),
E('Lire une courbe',r'Le capteur du modèle a $R=20,0-0,400\theta$, en kΩ et °C, entre 0 et 40 °C.',[r'Lire R à 20 °C.',r'Décrire le sens de variation.'],[r'$R=20,0-0,400\times20=\qty{12,0}{k\ohm}$.',r'La résistance diminue lorsque la température augmente sur le domaine étudié.'],'capteur-courbe'),
E('Une température inconnue',r'On mesure $R=\qty{10,0}{k\ohm}$ pour le capteur du modèle local.',[r'Déterminer la température.',r'Vérifier qu’elle appartient à la gamme.'],[r'$\theta=(20,0-10,0)/0,400=25,0\,^{\circ}\mathrm C$.',r'25 °C est entre 0 et 40 °C : on reste dans le domaine d’étalonnage.']),
E('Une conversion numérique',r'Un convertisseur fictif donne 0 pour 0 V et 1000 pour 5,00 V, de façon linéaire.',[r'Quelle tension correspond au code 600 ?',r'Quel code correspond à 1,25 V ?'],[r'$U=5,00\times600/1000=\qty{3,00}{V}$.',r'$k=1000\times1,25/5,00=250$.']),
E('Un pont simple',r'$U_0=5,00$ V, $R_0=10,0$ kΩ et $R_c=10,0$ kΩ.',[r'Calculer le courant dans les résistances en série.',r'Calculer la tension mesurée aux bornes de $R_c$.'],[r'$I=5,00/20000=\qty{0,250}{mA}$.',r'$U=R_cI=10000\times0,000250=\qty{2,50}{V}$.'],'pont-capteur'),
E('La grandeur utile',r'Une courbe fournit R en fonction de l’éclairement.',[r'Quelle grandeur veut-on déduire d’une résistance mesurée ?',r'Pourquoi faut-il un étalonnage avant la mesure inconnue ?'],[r'L’éclairement reçu par le capteur.',r'Il faut connaître la correspondance entre réponse électrique et grandeur recherchée, dans les conditions d’utilisation.']),
E('Une résistance retrouvée',r'Dans le pont, $R_0=10,0$ kΩ, $U_0=5,00$ V et $U=2,00$ V. On fournit $R_c=R_0U/(U_0-U)$.',[r'Calculer $R_c$.',r'En déduire la température avec le modèle local.'],[r'$R_c=10,0\times2,00/(5,00-2,00)=\qty{6,67}{k\ohm}$.',r'$\theta=(20,0-6,67)/0,400\simeq33,3\,^{\circ}\mathrm C$.'],'pont-capteur'),
E('Hors domaine',r'Un capteur a été étalonné entre 0 et 40 °C. Un calcul par prolongement de la droite donne 75 °C.',[r'Pourquoi cette valeur n’est-elle pas validée ?',r'Comment étendre l’usage du capteur ?'],[r'Le modèle a seulement été testé de 0 à 40 °C ; le prolongement est une extrapolation.',r'Vérifier les limites du composant et effectuer un étalonnage adapté sur le nouveau domaine avec une référence.']),
E('Un seuil à programmer',r'Une alerte est souhaitée au-dessus de 30,0 °C. Pour le capteur, $R=20,0-0,400\theta$ en kΩ.',[r'Calculer la résistance au seuil.',r'Faut-il déclencher pour une résistance supérieure ou inférieure à ce seuil ?'],[r'$R_s=20,0-0,400\times30,0=\qty{8,00}{k\ohm}$.',r'Pour $R<8,00$ kΩ, puisque la résistance diminue quand la température augmente.']),
E('Choisir les axes en Python',r'On veut tracer une caractéristique d’étalonnage R=f($\theta$).',[r'Quel tableau placer en abscisse et en ordonnée ?',r'Quelles informations ajouter au graphique ?'],[r'La température en abscisse, la résistance en ordonnée.',r'Les noms des grandeurs, les unités, les points mesurés, la légende du modèle et le domaine de validité.']),
E('Une division impossible',r'Le programme calcule $R_c=R_0U/(U_0-U)$. La mesure renvoie $U=U_0$.',[r'Que se passe-t-il dans le calcul ?',r'Comment le programme doit-il réagir ?'],[r'Le dénominateur est nul : la formule ne donne aucune résistance finie.',r'Signaler une mesure hors domaine ou un défaut possible, vérifier le circuit et éviter la division. Il ne faut pas afficher une température arbitraire.']),
E('Deux sources d’erreur',r'Un capteur étalonné correctement donne une température instable alors que le bain semble stable.',[r'Citer deux causes possibles liées à la mesure.',r'Proposer une vérification expérimentale.'],[r'Mauvais contact, fluctuations de l’alimentation, bruit électrique ou stabilisation thermique insuffisante.',r'Vérifier les connexions et la référence de tension, attendre l’équilibre puis répéter avec un thermomètre de référence.'])],
E('Du code à l’alerte',r'Le montage utilise $U_0=5,00$ V et $R_0=10,0$ kΩ. Le convertisseur fictif donne 1000 unités pour 5,00 V. Le capteur suit $R_c(\mathrm{k}\Omega)=20,0-0,400\theta$ de 0 à 40 °C. Une acquisition renvoie 400.',[r'Calculer U puis $R_c$.',r'Déterminer la température et l’état d’une alerte au-dessus de 30 °C.',r'Proposer deux garde-fous dans le programme.'],[r'$U=5,00\times400/1000=2,00$ V ; $R_c=10,0\times2,00/(5,00-2,00)=6,67$ kΩ.',r'$\theta\simeq33,3\,^{\circ}\mathrm C$, donc l’alerte se déclenche dans ce modèle.',r'Rejeter les tensions proches de 5,00 V qui rendent le quotient instable ; vérifier que la température calculée reste dans le domaine 0 à 40 °C. Tester aussi les connexions et les valeurs limites.'],'pont-capteur',methode=r'Piste 1 : convertir l’entier en tension. Piste 2 : appliquer le pont puis l’étalonnage. Piste 3 : contrôler les domaines de chaque relation.',note=r'Une chaîne de mesure doit être validée à chaque étape : capteur, circuit, acquisition et calcul.'),
['Capteurs résistifs et exemples usuels','Courbe d’étalonnage d’une grandeur','Mesure avec un capteur','Microcontrôleur et chaîne d’acquisition','Python : nuage de points et modèle'])
